package org.pestinha.android;
import android.content.*;
import org.json.*;
import java.util.*;
import org.junit.*;
import static org.junit.Assert.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,manifest=Config.NONE)
public class NewsRepositoryTest {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();NewsRepository.prefs(c).edit().clear().commit();InterestsDialog.visible=false;}
 JSONObject row(String name) throws Exception {return new JSONObject().put("title",name).put("link","https://example.org/"+name).put("source",NewsRepository.URLS[0]).put("publisher","Agência Brasil");}
 @Test public void choicesMapToMatchingFeedsAndPreserveCustomUrls() throws Exception {NewsRepository.prefs(c).edit().putString("feeds",new JSONArray().put("https://example.org/custom").put("https://g1.globo.com/rss/g1/").toString()).commit();NewsRepository.select(c,new HashSet<>(Arrays.asList("Criptomoedas","Ciência")),true);JSONArray feeds=NewsRepository.array(c,"feeds");assertEquals(3,feeds.length());assertEquals("https://example.org/custom",feeds.getString(0));assertEquals("https://livecoins.com.br/feed/",feeds.getString(1));assertEquals("https://www.nasa.gov/feed/",feeds.getString(2));assertEquals(2,NewsRepository.array(c,"radarTopics").length());assertFalse(NewsRepository.askToday(c));assertTrue(NewsRepository.prefs(c).getBoolean("radarAuto",false));}
 @Test public void tooManyFeedsLeavesPreviousSelectionUntouched() throws Exception {JSONArray custom=new JSONArray();for(int i=0;i<5;i++)custom.put("https://example.org/feed"+i);NewsRepository.prefs(c).edit().putString("feeds",custom.toString()).commit();try{NewsRepository.select(c,new HashSet<>(Arrays.asList(NewsRepository.TOPICS)),true);fail();}catch(IllegalArgumentException expected){}assertEquals(custom.toString(),NewsRepository.array(c,"feeds").toString());assertFalse(NewsRepository.prefs(c).contains("radarGeneration"));}
 @Test public void noSubscriptionOrAutomaticNewsUntilSave() throws Exception {assertTrue(NewsRepository.askToday(c));assertFalse(NewsRepository.prefs(c).getBoolean("radarAuto",false));assertEquals(0,NewsRepository.array(c,"feeds").length());NewsRepository.skipToday(c);assertFalse(NewsRepository.askToday(c));assertEquals(0,NewsRepository.array(c,"feeds").length());NewsRepository.select(c,Collections.emptySet(),true);assertFalse(NewsRepository.prefs(c).getBoolean("radarAuto",true));}
 @Test public void allTopicsUseValidDistinctOfficialSources() throws Exception {Set<String> catalog=new HashSet<>();JSONArray rows=FeedCatalog.entries(c);for(int i=0;i<rows.length();i++)catalog.add(rows.getJSONObject(i).getString("url"));for(String url:NewsRepository.URLS)assertTrue(catalog.contains(url));NewsRepository.select(c,new HashSet<>(Arrays.asList(NewsRepository.TOPICS)),true);assertEquals(7,NewsRepository.array(c,"feeds").length());}
 @Test public void cooldownSeenAndOldCachePreventRepetitiveHeadlines() throws Exception {long now=System.currentTimeMillis();NewsRepository.select(c,Collections.singleton("Notícias"),true);JSONObject first=row("primeira"),second=row("segunda");NewsRepository.prefs(c).edit().putString("news",new JSONArray().put(first).put(second).toString()).putLong("newsAt",now).commit();assertEquals("primeira",NewsRepository.candidate(c,now).getString("title"));NewsRepository.shown(c,first);assertNull(NewsRepository.candidate(c,now));NewsRepository.prefs(c).edit().putLong("newsSpokenAt",now-21*60000L).commit();assertEquals("segunda",NewsRepository.candidate(c,now).getString("title"));InterestsDialog.visible=true;assertNull(NewsRepository.candidate(c,now));InterestsDialog.visible=false;NewsRepository.prefs(c).edit().putLong("newsAt",now-2*86400000L).commit();assertNull(NewsRepository.candidate(c,now));}
 @Test public void pauseAndReselectionInvalidatePendingGenerationAndCache() throws Exception {NewsRepository.select(c,Collections.singleton("Notícias"),true);String old=NewsRepository.generation(c);NewsRepository.automatic(c,false);assertNotEquals(old,NewsRepository.generation(c));assertNull(NewsRepository.candidate(c,System.currentTimeMillis()));NewsRepository.prefs(c).edit().putString("news","[{}]").commit();NewsRepository.select(c,Collections.singleton("Ciência"),false);assertEquals(0,NewsRepository.array(c,"news").length());assertFalse(NewsRepository.prefs(c).getBoolean("radarAuto",true));}
 @Test public void commentaryUsesPublisherTextWithoutInventedSummary() throws Exception {c.getSharedPreferences("pet",0).edit().putString("character","mimir").commit();String message=NewsRepository.message(c,row("<b>Texto do veículo</b>"));assertTrue(message.contains("Hmpf."));assertTrue(message.contains("Agência Brasil"));assertTrue(message.contains("Texto do veículo"));assertFalse(message.contains("<b>"));}
}
